'use strict';
(()=>{
  const catalog=[
    {id:'github',page:'projects',name:'GitHub',category:'development',glyph:'folder',description:'Keep your projects close.',detail:'Monitor saved repositories, recent pull requests, issues and workflow runs with your local GitHub CLI account.',access:'Read-only GitHub repository metadata using your existing CLI sign-in. Tokens stay with GitHub CLI; saved repository names stay private on this Mac.',kind:'github',docs:'https://github.com/OpenCoven/open-sesame/blob/main/docs/github-monitor-widget.md'},
    {id:'coven',page:'console',name:'Coven Familiars',category:'agents',glyph:'chat',description:'Your familiars, in conversation.',detail:'Connect local Coven, choose any familiar from its roster, and chat with streamed replies and saved conversations.',access:'Messages run only when you press Send. Coven supplies the familiar identity and provider sign-in. Replies default to read-only; full access always needs a native confirmation for that exact reply.',kind:'familiars',docs:'https://github.com/OpenCoven/open-sesame/blob/main/docs/coven-familiars-integration.md'},
    {id:'spotify',page:'media',name:'Spotify',category:'media',logo:'spotify',description:'Your music, within reach.',detail:'Open songs, albums, or playlists in Media. Optional account access in the Mac app or HTTPS browser reads your profile; it does not import your library.',access:'Basic account profile. Embedded playback follows Spotify’s own sign-in and availability.',kind:'music',docs:'https://developer.spotify.com/documentation/web-api/tutorials/code-pkce-flow'},
    {id:'apple',page:'media',name:'Apple Music',category:'media',logo:'applemusic',description:'A soundtrack for your flow.',detail:'Open Apple Music links in Media. Browser MusicKit account playback needs your own server-issued developer token.',access:'Apple Music account authorization. Full playback requires an eligible subscription.',kind:'music',docs:'https://developer.apple.com/musickit/'},
    {id:'youtube',page:'media',name:'YouTube',category:'media',logo:'youtube',description:'Videos, music, and playlists.',detail:'Play a link in Media without connecting. Optional Google browser authorization reads your channel identity; it does not import playlists.',access:'Read-only YouTube account access. Open Sesame does not publish or change your videos.',kind:'music',docs:'https://developers.google.com/youtube/v3/guides/auth/client-side-web-apps'},
    {id:'claude',page:'live',name:'Claude Code',category:'agents',logo:'claude',description:'Ask more of your transcript.',detail:'Use the Claude Code CLI on your Mac to answer questions about your Live transcript.',access:'Your question, recent transcript, and recent Q&A are sent only when you ask. Uses your terminal sign-in.',kind:'agent',docs:'https://code.claude.com/docs/en/setup'},
    {id:'codex',page:'live',name:'Codex',category:'agents',logo:'openai',description:'A second mind for your notes.',detail:'Use the Codex CLI on your Mac to answer questions about your Live transcript.',access:'Your question, recent transcript, and recent Q&A are sent only when you ask. Uses your terminal sign-in.',kind:'agent',docs:'https://developers.openai.com/codex/cli/'},
    {id:'rss',page:'reader',name:'RSS & Atom',category:'reading',glyph:'rss',description:'Follow what matters to you.',detail:'Bring feeds and saved articles into Reader. Add a feed URL or discover one from a website.',access:'Fetches your subscribed feeds when refreshed. Subscriptions and read states stay on this device.',kind:'feeds'}
  ];
  function status(plugin,{music={},desktop=false,agents=null,error='',feedCount=0,familiars={},github={}}={}){
    if(plugin.kind==='music'){const s=music[plugin.id]||{};return s.supported===false?{label:'Browser sign-in required',tone:'idle',action:'View setup'}:s.connected?{label:'Connected',tone:'connected',action:'Manage'}:s.busy||s.loading?{label:'Connecting',tone:'pending',action:'View'}:s.error||s.expired?{label:s.expired?'Session expired':'Needs attention',tone:'attention',action:'Reconnect'}:{label:s.configured?'Not connected':'Setup needed',tone:'idle',action:s.configured?'Connect':'Set up'};}
    if(plugin.kind==='github')return !desktop?{label:'Desktop required',tone:'idle',action:'Set up'}:github.connected?{label:github.count+' repositories',tone:'connected',action:'Open monitor'}:{label:'Read-only monitor',tone:'idle',action:'Open monitor'};
    if(plugin.kind==='familiars')return !desktop?{label:'Desktop required',tone:'idle',action:'Set up'}:familiars.connected?{label:familiars.count+' familiars',tone:'connected',action:'Open'}:familiars.error?{label:'Needs attention',tone:'attention',action:'Reconnect'}:{label:'Ready to connect',tone:'idle',action:'Connect'};
    if(plugin.kind==='agent')return !desktop?{label:'Desktop required',tone:'idle',action:'Set up'}:error?{label:'Check connection',tone:'attention',action:'Details'}:agents===null?{label:'Not checked',tone:'pending',action:'Check'}:agents[plugin.id]===true?{label:'CLI detected',tone:'detected',action:'Open'}:{label:'Not installed',tone:'idle',action:'Set up'};
    return {label:feedCount?feedCount+' feed'+(feedCount===1?'':'s'):'No feeds yet',tone:feedCount?'configured':'idle',action:feedCount?'Manage':'Add feed'};
  }
  function setup(plugin,{music={}}={}){
    const steps={
      github:['Open the GitHub monitor. It uses your existing GitHub CLI account on this Mac.','If needed, copy the sign-in command, run it in Terminal and complete the GitHub browser flow, then choose Connect. Never paste a token into the widget.','Add owner/repository or its GitHub URL. Switch between saved projects to see recent pull requests, open issues and workflow runs.'],
      coven:['Install and configure Coven from its official guide, using provider sign-in in your terminal.','Choose Console → Familiars → Connect Coven, then select a familiar from your installed roster.','Type a message and explicitly Send. Discovery and reopening never send a test prompt.'],
      claude:['Install Claude Code from its official guide and sign in through the CLI.','Reopen the desktop companion and choose Widgets → Refresh. CLI detected confirms installation, not sign-in.','Choose Live, select Claude Code, prepare a transcript, then explicitly ask a question.'],
      codex:['Install Codex from its official guide and sign in through the CLI.','Reopen the desktop companion and choose Widgets → Refresh. CLI detected confirms installation, not sign-in.','Choose Live, select Codex, prepare a transcript, then explicitly ask a question.'],
      spotify:['Open Media → Music → Spotify and choose Connect. Open Sesame includes its public Spotify client configuration.','Choose Continue with Spotify and finish sign-in in the provider window. You do not need to create a Spotify developer app.','Return to Open Sesame. Account connection reads your profile; the embedded player handles its own playback sign-in.'],
      youtube:['For playback, paste a YouTube video or playlist into Media. Account connection is optional.','For account access, use the HTTPS browser version. Enable YouTube Data API v3 and configure a Google web OAuth client and consent/test-user access.','Register the exact JavaScript origin shown in App setup, enter only the public client ID, then Continue with Google and allow read-only YouTube access.'],
      apple:['Open Apple Music links in Media; embedded previews use their own provider controls.','For MusicKit account playback, use the HTTPS browser version and obtain a short-lived, origin-scoped developer JWT from your own server. Keep the .p8 signing key on that server.','Enter the JWT only in the masked session field, save it, then authorize your Apple Music account. Never put a token or signing key in the app bundle.'],
      rss:['Choose Reader → Add and select Feed or Website.','Enter a public, credential-free feed or website URL and follow it.','Refresh Reader. Subscriptions and read state are stored on this device.']
    };
    const repairs={github:'Check the account and repository access in GitHub CLI. Organization SSO or private repositories may need authorization in GitHub. A section without access stays unavailable. Offline snapshots are labeled and rate limits pause requests for five minutes.',coven:'If the roster is missing, check the installed Coven CLI and engine in your terminal. Each familiar needs an existing dedicated workspace. Use the Familiars reconnect action after fixing setup.',claude:'If detection fails, check the CLI installation and the app’s PATH. If a request requires sign-in, complete it in the terminal, update the CLI, then retry explicitly.',codex:'If detection fails, check the CLI installation and the app’s PATH. If a request requires sign-in, complete it in the terminal, update the CLI, then retry explicitly.',spotify:'If Spotify rejects the redirect, Open Sesame’s maintainer must register the exact callback shown in App setup. Check account access and reconnect after an expired session. You do not need your own client ID or a client secret. Account connection does not sign the embedded player in.',youtube:'For origin mismatch, register the exact scheme, host, and port. Check API enablement, consent/test-user access, popup permission, and the requested read-only scope.',apple:'For rejected authorization, request a fresh developer JWT for this origin from your server and check its expiry, signing configuration, and account eligibility. Do not paste a signing key to work around an error.',rss:'If a URL fails, check that it publishes RSS/Atom or use Website discovery. Use the desktop companion for feeds the browser cannot fetch across origins.'};
    const blocked=plugin.kind==='music'&&music[plugin.id]?.supported===false;
    return {steps:steps[plugin.id]||[],repair:repairs[plugin.id]||'',note:blocked?'Account sign-in is unavailable in this host. Use the HTTPS browser version; music and video links still open here.':plugin.kind==='github'?'GET-only repository monitoring. The widget never posts, merges, reruns or edits GitHub content. It does not display GitHub Projects boards.':plugin.kind==='agent'?'CLI detection is read-only. Provider sign-in is checked only when you explicitly ask.':plugin.kind==='familiars'?'Coven owns provider sign-in and familiar workspaces. No model keys belong in this widget.':plugin.kind==='feeds'?'No account or API key is needed for public feeds.':'Only public OAuth client IDs may be saved. Developer JWTs and user tokens are session-only; signing keys and client secrets never belong here.'};
  }
  function filter(items,query,category,connected,context){const q=query.trim().toLowerCase();return items.filter(p=>(category==='all'||p.category===category)&&(!q||(p.name+' '+p.description+' '+p.category).toLowerCase().includes(q))&&(!connected||['connected','detected','configured'].includes(status(p,context).tone)));}
  const api={catalog,status,setup,filter};if(typeof module!=='undefined')module.exports=api;else window.OpenSesamePluginsModel=api;
})();
